import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/bivariate/bivariate_2021_no2_energy.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

# Create neighbor dictionary
neighbors = {}
for _, row in adj_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in neighbors:
        neighbors[borough] = []
    neighbors[borough].append(neighbor)

# Create energy map
energy_map = df.set_index('borough')['Energy_value'].to_dict()

# Compute spatial lag of Energy for each borough
spatial_lag_energy = []
for index, row in df.iterrows():
    borough = row['borough']
    if borough not in neighbors:
        spatial_lag_energy.append(np.nan)
        continue
    neighbor_energies = []
    for neighbor in neighbors[borough]:
        if neighbor in energy_map:
            neighbor_energy = energy_map[neighbor]
            if not np.isnan(neighbor_energy):
                neighbor_energies.append(neighbor_energy)
    if len(neighbor_energies) == 0:
        spatial_lag_energy.append(np.nan)
    else:
        spatial_lag_energy.append(np.mean(neighbor_energies))

df['spatial_lag_energy'] = spatial_lag_energy

# Compute observed correlation
observed_df = df.dropna(subset=['NO2_value', 'spatial_lag_energy'])
observed_corr = np.corrcoef(observed_df['NO2_value'], observed_df['spatial_lag_energy'])[0, 1]

# Permutation test
original_energy = df['Energy_value'].copy()
perm_corrs = []
for _ in range(500):
    shuffled_energy = original_energy.sample(frac=1).reset_index(drop=True)
    shuffled_energy_map = dict(zip(df['borough'], shuffled_energy))
    shuffled_spatial_lag = []
    for index, row in df.iterrows():
        borough = row['borough']
        if borough not in neighbors:
            shuffled_spatial_lag.append(np.nan)
            continue
        neighbor_energies = []
        for neighbor in neighbors[borough]:
            if neighbor in shuffled_energy_map:
                neighbor_energy = shuffled_energy_map[neighbor]
                if not np.isnan(neighbor_energy):
                    neighbor_energies.append(neighbor_energy)
        if len(neighbor_energies) == 0:
            shuffled_spatial_lag.append(np.nan)
        else:
            shuffled_spatial_lag.append(np.mean(neighbor_energies))
    perm_df = df.copy()
    perm_df['spatial_lag_energy'] = shuffled_spatial_lag
    perm_df = perm_df.dropna(subset=['NO2_value', 'spatial_lag_energy'])
    if len(perm_df) < 2:
        corr = np.nan
    else:
        corr = np.corrcoef(perm_df['NO2_value'], perm_df['spatial_lag_energy'])[0, 1]
    perm_corrs.append(corr)

# Calculate p-value
observed_sign = np.sign(observed_corr)
extreme_count = 0
for corr in perm_corrs:
    if not np.isnan(corr):
        if (observed_sign > 0 and corr >= observed_corr) or (observed_sign < 0 and corr <= observed_corr):
            extreme_count += 1
p_value = (extreme_count + 1) / (500 + 1)

print('Observed correlation:', observed_corr)
print('p-value:', p_value)

if p_value < 0.05:
    if observed_corr > 0:
        print("FINAL ANSWER: POSITIVE (test statistic (a real number) = {}, p = {})".format(observed_corr, p_value))
    else:
        print("FINAL ANSWER: NEGATIVE (test statistic (a real number) = {}, p = {})".format(observed_corr, p_value))
else:
    print("FINAL ANSWER: NOT SIGNIFICANT (test statistic (a real number) = {}, p = {})".format(observed_corr, p_value))
